package edu.pe.cibertec.saibm.inventario.domain.service; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.HexFormat; public final class RequestHasher {public String hold(String b,int q,String e){return sha(b+"|"+q+"|"+e);}public String transition(String b,String op){return sha(b+"|"+op);}private String sha(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
